        BalmLoadContexts.register(modId, forgeLoadContext);

        initializer.run();

        final var modEventBus = forgeLoadContext.modEventBus();
        DeferredRegisters.register(modId, modEventBus);
        ModBusEventRegisters.register(modId, modEventBus);
    }

